31	// HybridConfig configures the Hybrid selector that combines multiple methods
32	// Based on arXiv:2404.14618 - Hybrid LLM: Cost-Efficient Quality-Aware Query Routing
33	type HybridConfig struct {
34		// ExperienceWeight is the weight for feedback-derived experience contribution (0-1)
35		ExperienceWeight float64 `yaml:"experience_weight"`
36	
37		// RouterDCWeight is the weight for embedding similarity contribution (0-1)
38		RouterDCWeight float64 `yaml:"router_dc_weight"`
39	
40		// AutoMixWeight is the weight for POMDP value contribution (0-1)
41		AutoMixWeight float64 `yaml:"automix_weight"`
42	
43		// CostWeight is the weight for cost consideration (0-1)
44		CostWeight float64 `yaml:"cost_weight"`
45	
46		// QualityGapThreshold triggers escalation to larger models
47		QualityGapThreshold float64 `yaml:"quality_gap_threshold"`
48	
49		// UseMLP enables MLP-based quality gap prediction (advanced)
50		UseMLP bool `yaml:"use_mlp"`
51	
52		// NormalizeScores normalizes component scores before combination
53		NormalizeScores bool `yaml:"normalize_scores"`
54	}
55	
56	// DefaultHybridConfig returns the default Hybrid configuration
57	func DefaultHybridConfig() *HybridConfig {
58		return &HybridConfig{
59			ExperienceWeight:    0.3,
60			RouterDCWeight:      0.3,
61			AutoMixWeight:       0.2,
62			CostWeight:          0.2,
63			QualityGapThreshold: 0.1,
64			UseMLP:              false,
65			NormalizeScores:     true,
66		}
67	}
68	
69	// HybridSelector combines multiple selection methods for robust routing
70	// It uses weighted combination of experience ratings, embedding similarity,
71	// and POMDP values, with optional cost-aware optimization.
72	type HybridSelector struct {
73		config *HybridConfig
74	
75		// Component selectors
76		eloSelector      *EloSelector
77		routerDCSelector *RouterDCSelector
78		autoMixSelector  *AutoMixSelector
79	
80		// Model costs for cost-aware selection
81		modelCosts map[string]float64
82	
83		// lookupTable provides data-driven values (e.g. quality-gap estimates)
84		// that replace hardcoded config constants. May be nil.
85		lookupTable lookuptable.LookupTable
86	}
87	
88	// NewHybridSelector creates a new Hybrid selector
89	func NewHybridSelector(cfg *HybridConfig) *HybridSelector {
90		if cfg == nil {
91			cfg = DefaultHybridConfig()
92		}
93	
94		return &HybridSelector{
95			config:           cfg,
96			eloSelector:      NewEloSelector(DefaultEloConfig()),
97			routerDCSelector: NewRouterDCSelector(DefaultRouterDCConfig()),
98			autoMixSelector:  NewAutoMixSelector(DefaultAutoMixConfig()),
99			modelCosts:       make(map[string]float64),
100		}
101	}
102	
