148	// SetLookupTable attaches a lookup table for data-driven constant resolution.
149	func (h *HybridSelector) SetLookupTable(lt lookuptable.LookupTable) {
150		h.lookupTable = lt
151	}
152	
153	// resolveQualityGap returns the quality-gap threshold between currentModel and
154	// candidateModel for the given task family. It first checks the lookup table;
155	// if no entry is found it falls back to config.QualityGapThreshold.
156	//
157	// TODO: integrate into model upgrade decision logic in Select.
158	//
159	//lint:ignore U1000 reserved for upcoming lookup-table consumption by model upgrade decision logic
160	func (h *HybridSelector) resolveQualityGap(taskFamily, currentModel, candidateModel string) float64 {
161		if h.lookupTable != nil && taskFamily != "" && currentModel != "" && candidateModel != "" {
162			if gap, ok := h.lookupTable.QualityGap(taskFamily, currentModel, candidateModel); ok {
163				return gap
164			}
165		}
166		return h.config.QualityGapThreshold
167	}
168	
169	// Select chooses the best model by combining multiple selection methods
170	func (h *HybridSelector) Select(ctx context.Context, selCtx *SelectionContext) (*SelectionResult, error) {
171		if err := ValidateSelectionContext(selCtx); err != nil {
172			return nil, err
173		}
174	
175		// Collect scores from each component
176		componentScores := make(map[string]map[string]float64)
177		var componentResults []*SelectionResult
178	
179		// Get feedback-derived experience scores
180		if h.eloSelector != nil && h.config.ExperienceWeight > 0 {
181			result, err := h.eloSelector.Select(ctx, selCtx)
182			if err == nil && result != nil {
183				componentScores["experience"] = result.AllScores
184				componentResults = append(componentResults, result)
185			}
186		}
187	
188		// Get RouterDC scores
189		if h.routerDCSelector != nil && h.config.RouterDCWeight > 0 {
190			result, err := h.routerDCSelector.Select(ctx, selCtx)
191			if err == nil && result != nil {
192				componentScores["router_dc"] = result.AllScores
193				componentResults = append(componentResults, result)
194			}
195		}
196	
197		// Get AutoMix scores
198		if h.autoMixSelector != nil && h.config.AutoMixWeight > 0 {
199			result, err := h.autoMixSelector.Select(ctx, selCtx)
200			if err == nil && result != nil {
201				componentScores["automix"] = result.AllScores
202				componentResults = append(componentResults, result)
203			}
204		}
205	
206		// Normalize scores if enabled
207		if h.config.NormalizeScores {
208			for component, scores := range componentScores {
209				componentScores[component] = h.normalizeScores(scores)
210			}
211		}
212	
213		// Combine scores with weights
214		combinedScores := h.combineScores(componentScores, selCtx.CandidateModels)
215	
216		// Apply cost adjustment
217		if h.config.CostWeight > 0 {
218			h.applyCostAdjustment(combinedScores, selCtx.CostWeight)
219		}
220	
221		h.applyCacheAffinity(combinedScores, selCtx)
222	
223		logging.Infof("[HybridSelector] Combining scores (weights: experience=%.2f, dc=%.2f, am=%.2f, cost=%.2f):",
224			h.config.ExperienceWeight, h.config.RouterDCWeight, h.config.AutoMixWeight, h.config.CostWeight)
225		for _, model := range selCtx.CandidateModels {
226			var experienceScore, dcScore, amScore float64
227			if scores, ok := componentScores["experience"]; ok {
228				experienceScore = scores[model.Model]
229			}
230			if scores, ok := componentScores["router_dc"]; ok {
231				dcScore = scores[model.Model]
232			}
233			if scores, ok := componentScores["automix"]; ok {
234				amScore = scores[model.Model]
235			}
236			logging.Infof("[HybridSelector]   %s: experience=%.4f, dc=%.4f, am=%.4f → combined=%.4f",
237				model.Model, experienceScore, dcScore, amScore, combinedScores[model.Model])
238		}
239	
240		bestModel, bestScore := h.selectBestModel(selCtx.CandidateModels, combinedScores)
241	
242		if bestModel == nil {
243			return nil, fmt.Errorf("could not select a model")
244		}
245	
246		// Calculate confidence from component agreement
247		confidence := h.calculateConfidence(componentResults, bestModel.Model)
248	
249		h.recordComponentAgreement(componentResults, bestModel.Model)
250	
251		// Build reasoning
252		reasoning := h.buildReasoning(componentScores, bestModel.Model)
253	
254		logging.Infof("[HybridSelector] Selected model %s (score=%.4f, confidence=%.2f, components=%d)",
255			bestModel.Model, bestScore, confidence, len(componentResults))
256	
257		return &SelectionResult{
258			SelectedModel: bestModel.Model,
259			LoRAName:      bestModel.LoRAName,
260			Score:         bestScore,
261			Confidence:    confidence,
262			Method:        MethodHybrid,
263			Reasoning:     reasoning,
264			AllScores:     combinedScores,
265		}, nil
266	}
267	
268	func (h *HybridSelector) applyCacheAffinity(combinedScores map[string]float64, selCtx *SelectionContext) {
269		if selCtx.CacheAffinityCtx == nil {
270			return
271		}
272	
273		affinityResult := ComputeCacheAffinityAdjustments(
274			selCtx.CacheAffinityCtx, selCtx.CandidateModels, combinedScores)
275		for model, adj := range affinityResult.Adjustments {
276			if adj != 0 {
277				combinedScores[model] += adj
278			}
279		}
280	}
281	
282	func (h *HybridSelector) selectBestModel(candidates []config.ModelRef, combinedScores map[string]float64) (*config.ModelRef, float64) {
283		var bestModel *config.ModelRef
284		var bestScore float64
285	
286		for i := range candidates {
287			model := &candidates[i]
288			score := combinedScores[model.Model]
289	
290			if score > bestScore || bestModel == nil {
291				bestScore = score
292				bestModel = model
293			}
294		}
295	
296		return bestModel, bestScore
297	}
298	
299	func (h *HybridSelector) recordComponentAgreement(componentResults []*SelectionResult, bestModel string) {
300		if len(componentResults) <= 1 {
301			return
302		}
303	
304		agreementRatio := float64(0)
305		for _, r := range componentResults {
306			if r.SelectedModel == bestModel {
307				agreementRatio++
308			}
309		}
310		agreementRatio /= float64(len(componentResults))
311		RecordComponentAgreement(agreementRatio)
312	}
