314	// UpdateFeedback propagates feedback to all component selectors
315	func (h *HybridSelector) UpdateFeedback(ctx context.Context, feedback *Feedback) error {
316		if err := h.normalizeFeedbackForComponents(feedback); err != nil {
317			return err
318		}
319	
320		var errs []error
321		updatedComponents := 0
322	
323		if h.eloSelector != nil {
324			if err := h.eloSelector.UpdateFeedback(ctx, feedback); err != nil {
325				errs = append(errs, fmt.Errorf("elo: %w", err))
326			} else {
327				updatedComponents++
328			}
329		}
330	
331		if h.routerDCSelector != nil {
332			if err := h.routerDCSelector.UpdateFeedback(ctx, feedback); err != nil {
333				errs = append(errs, fmt.Errorf("router_dc: %w", err))
334			} else {
335				updatedComponents++
336			}
337		}
338	
339		if h.autoMixSelector != nil {
340			if err := h.autoMixSelector.UpdateFeedback(ctx, feedback); err != nil {
341				errs = append(errs, fmt.Errorf("automix: %w", err))
342			} else {
343				updatedComponents++
344			}
345		}
346	
347		if len(errs) > 0 {
348			return fmt.Errorf("feedback update errors: %w", errors.Join(errs...))
349		}
350	
351		logging.Debugf("[HybridSelector] Propagated feedback to %d components", updatedComponents)
352		return nil
353	}
354	
355	func (h *HybridSelector) normalizeFeedbackForComponents(feedback *Feedback) error {
356		if err := NormalizeFeedback(feedback); err != nil {
357			return err
358		}
359		if h.requiresWinnerFeedback() && feedback.WinnerModel == "" {
360			return ErrFeedbackWinnerRequired
361		}
362		return nil
363	}
364	
365	func (h *HybridSelector) requiresWinnerFeedback() bool {
366		return h.routerDCSelector != nil || h.autoMixSelector != nil
367	}
368	
369	// combineScores combines scores from all components with weights
370	func (h *HybridSelector) combineScores(componentScores map[string]map[string]float64, candidates []config.ModelRef) map[string]float64 {
371		result := make(map[string]float64)
372	
373		// Initialize with zeros
374		for _, c := range candidates {
375			result[c.Model] = 0.0
376		}
377	
378		// Weight mapping
379		weights := map[string]float64{
380			"experience": h.config.ExperienceWeight,
381			"router_dc":  h.config.RouterDCWeight,
382			"automix":    h.config.AutoMixWeight,
383		}
384	
385		// Calculate total weight for normalization
386		totalWeight := 0.0
387		for component, scores := range componentScores {
388			if len(scores) > 0 {
389				totalWeight += weights[component]
390			}
391		}
392	
393		if totalWeight == 0 {
394			// No component scores available, use uniform
395			for model := range result {
396				result[model] = 1.0 / float64(len(candidates))
397			}
398			return result
399		}
400	
401		// Weighted combination
402		for component, scores := range componentScores {
403			weight := weights[component]
404			for model, score := range scores {
405				result[model] += (weight / totalWeight) * score
406			}
407		}
408	
409		return result
410	}
411	
412	// normalizeScores normalizes scores to [0, 1] range using min-max normalization
413	func (h *HybridSelector) normalizeScores(scores map[string]float64) map[string]float64 {
414		if len(scores) == 0 {
415			return scores
416		}
417	
418		minScore := math.Inf(1)
419		maxScore := math.Inf(-1)
420	
421		for _, s := range scores {
422			if s < minScore {
423				minScore = s
424			}
425			if s > maxScore {
426				maxScore = s
427			}
428		}
429	
430		// Avoid division by zero
431		if maxScore == minScore {
432			result := make(map[string]float64)
433			for model := range scores {
434				result[model] = 0.5
435			}
436			return result
437		}
438	
439		result := make(map[string]float64)
440		for model, s := range scores {
441			result[model] = (s - minScore) / (maxScore - minScore)
442		}
443	
444		return result
445	}
446	
447	// applyCostAdjustment applies cost-based score adjustment
448	func (h *HybridSelector) applyCostAdjustment(scores map[string]float64, costWeight float64) {
449		if len(h.modelCosts) == 0 || costWeight <= 0 {
450			return
451		}
452	
453		// Find min and max costs
454		minCost, maxCost := math.MaxFloat64, 0.0
455		for model := range scores {
456			if cost, ok := h.modelCosts[model]; ok {
457				if cost < minCost {
458					minCost = cost
459				}
460				if cost > maxCost {
461					maxCost = cost
462				}
463			}
464		}
465	
466		if maxCost == minCost {
467			return
468		}
469	
470		// Adjust scores: cheaper models get bonus
471		for model := range scores {
472			if cost, ok := h.modelCosts[model]; ok {
473				normalizedCost := (cost - minCost) / (maxCost - minCost)
474				costBonus := (1.0 - normalizedCost) * costWeight * h.config.CostWeight
475				scores[model] *= (1.0 + costBonus)
476			}
477		}
478	}
479	
480	// calculateConfidence calculates confidence based on component agreement
481	func (h *HybridSelector) calculateConfidence(results []*SelectionResult, selectedModel string) float64 {
482		if len(results) == 0 {
483			return 0.5
484		}
485	
486		// Count how many components agree on the selected model
487		agreements := 0
488		totalConfidence := 0.0
489	
490		for _, r := range results {
491			if r.SelectedModel == selectedModel {
492				agreements++
493			}
494			totalConfidence += r.Confidence
495		}
496	
497		// Agreement ratio
498		agreementRatio := float64(agreements) / float64(len(results))
499	
500		// Average component confidence
501		avgConfidence := totalConfidence / float64(len(results))
502	
503		// Combine: higher agreement and confidence = more confident
504		return (agreementRatio + avgConfidence) / 2.0
505	}
506	
507	// buildReasoning creates a human-readable explanation
508	func (h *HybridSelector) buildReasoning(componentScores map[string]map[string]float64, selectedModel string) string {
509		parts := []string{}
510	
511		if scores, ok := componentScores["experience"]; ok {
512			if score, ok := scores[selectedModel]; ok {
513				parts = append(parts, fmt.Sprintf("Experience=%.3f", score))
514			}
515		}
516	
517		if scores, ok := componentScores["router_dc"]; ok {
518			if score, ok := scores[selectedModel]; ok {
519				parts = append(parts, fmt.Sprintf("RouterDC=%.3f", score))
520			}
521		}
522	
523		if scores, ok := componentScores["automix"]; ok {
524			if score, ok := scores[selectedModel]; ok {
525				parts = append(parts, fmt.Sprintf("AutoMix=%.3f", score))
526			}
527		}
528	
529		weightsStr := fmt.Sprintf("weights=[elo:%.2f, dc:%.2f, am:%.2f, cost:%.2f]",
530			h.config.ExperienceWeight, h.config.RouterDCWeight, h.config.AutoMixWeight, h.config.CostWeight)
531	
532		if len(parts) > 0 {
533			return fmt.Sprintf("Hybrid combination: [%s], %s", strings.Join(parts, " "), weightsStr)
534		}
535		return fmt.Sprintf("Hybrid selection with %s", weightsStr)
536	}
537	
538	// InitializeFromConfig initializes all component selectors from configuration
539	func (h *HybridSelector) InitializeFromConfig(modelConfig map[string]config.ModelParams, categories []config.Category) {
540		if h.eloSelector != nil {
541			h.eloSelector.InitializeFromConfig(modelConfig, categories)
542		}
543	
544		if h.autoMixSelector != nil {
545			h.autoMixSelector.InitializeFromConfig(modelConfig)
546		}
547	
548		// Set costs from config
549		for model, params := range modelConfig {
550			if params.Pricing.PromptPer1M > 0 {
551				h.modelCosts[model] = params.Pricing.PromptPer1M
552			}
553		}
554	
555		logging.ComponentEvent("selection", "hybrid_selector_initialized", map[string]interface{}{
556			"model_count": len(modelConfig),
557		})
558	}
