17	package selection
18	
19	import (
20		"context"
21		"fmt"
22		"math"
23		"sort"
24		"sync"
25	
26		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
27		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
28	)
29	
30	// DefaultEloRating is the initial Elo rating for new models
31	const DefaultEloRating = 1500.0
32	
33	// EloKFactor controls how much ratings change per comparison
34	// Higher values = faster adaptation but more volatility
35	const EloKFactor = 32.0
36	
37	// EloMinRatingFromScore is the base rating when converting static scores (0-1) to Elo
38	const EloMinRatingFromScore = 1000.0
39	
40	// EloRatingRange is the rating range for score conversion (scores 0-1 map to 1000-2000)
41	const EloRatingRange = 1000.0
42	
43	// EloConfig configures the Elo-based model selector
44	type EloConfig struct {
45		// InitialRating is the starting Elo rating for new models
46		InitialRating float64 `yaml:"initial_rating"`
47	
48		// KFactor controls rating volatility (higher = more volatile)
49		KFactor float64 `yaml:"k_factor"`
50	
51		// CategoryWeighted enables per-category Elo ratings
52		CategoryWeighted bool `yaml:"category_weighted"`
53	
54		// DecayFactor applies time decay to old comparisons (0-1, 0 = no decay)
55		DecayFactor float64 `yaml:"decay_factor"`
56	
57		// MinComparisons is minimum comparisons before a rating is considered stable
58		MinComparisons int `yaml:"min_comparisons"`
59	
60		// CostScalingFactor scales cost consideration (0 = ignore cost)
61		CostScalingFactor float64 `yaml:"cost_scaling_factor"`
62	
63		// StoragePath is the file path for persisting Elo ratings (optional)
64		// If set, ratings are loaded on startup and saved after each feedback update
65		// Example: "/var/lib/vsr/elo_ratings.json"
66		StoragePath string `yaml:"storage_path,omitempty"`
67	
68		// AutoSaveInterval is the interval for automatic saves (default: 30s)
69		// Only used when StoragePath is set
70		AutoSaveInterval string `yaml:"auto_save_interval,omitempty"`
71	}
72	
73	// DefaultEloConfig returns the default Elo configuration
74	func DefaultEloConfig() *EloConfig {
75		return &EloConfig{
76			InitialRating:     DefaultEloRating,
77			KFactor:           EloKFactor,
78			CategoryWeighted:  true,
79			DecayFactor:       0.0,
80			MinComparisons:    5,
81			CostScalingFactor: 0.0,
82		}
83	}
84	
85	// ModelRating stores the Elo rating and metadata for a model
86	type ModelRating struct {
87		Model       string  `json:"model"`
88		Rating      float64 `json:"rating"`
89		Comparisons int     `json:"comparisons"`
90		Wins        int     `json:"wins"`
91		Losses      int     `json:"losses"`
92		Ties        int     `json:"ties"`
93	}
94	
95	// EloSelector implements Elo rating-based model selection
96	// Based on RouteLLM paper (arXiv:2406.18665) using Bradley-Terry model
97	type EloSelector struct {
98		config *EloConfig
99	
100		// Global ratings (not category-specific)
101		globalRatings map[string]*ModelRating
102		globalMu      sync.RWMutex
103	
104		// Category-specific ratings (decision name -> model -> rating)
105		categoryRatings map[string]map[string]*ModelRating
106		categoryMu      sync.RWMutex
107	
108		// Model costs for cost-aware selection (model -> cost per 1M tokens)
109		modelCosts map[string]float64
110		costMu     sync.RWMutex
111	
112		// Storage backend for persisting ratings (optional)
113		storage EloStorage
114	}
115	
116	// NewEloSelector creates a new Elo-based selector
117	func NewEloSelector(cfg *EloConfig) *EloSelector {
118		if cfg == nil {
119			cfg = DefaultEloConfig()
120		}
121		selector := &EloSelector{
122			config:          cfg,
123			globalRatings:   make(map[string]*ModelRating),
124			categoryRatings: make(map[string]map[string]*ModelRating),
125			modelCosts:      make(map[string]float64),
126		}
127	
128		// Initialize storage if path is configured
129		if cfg.StoragePath != "" {
130			storage, err := NewFileEloStorage(cfg.StoragePath)
131			if err != nil {
132				logging.ComponentErrorEvent("selection", "elo_storage_init_failed", map[string]interface{}{
133					"storage_path": cfg.StoragePath,
134					"error":        err.Error(),
135				})
136			} else {
137				selector.storage = storage
138	
139				// Load existing ratings from storage
140				if err := selector.loadFromStorage(); err != nil {
141					logging.ComponentWarnEvent("selection", "elo_storage_load_failed", map[string]interface{}{
142						"storage_path": cfg.StoragePath,
143						"error":        err.Error(),
144					})
145				}
146	
147				// Start auto-save with a validated interval (positive and below
148				// the documented maximum; falls back to the default otherwise).
149				interval := resolveAutoSaveInterval(cfg.AutoSaveInterval)
150				storage.StartAutoSave(interval, selector.getAllRatingsForStorage)
151				logging.ComponentEvent("selection", "elo_storage_initialized", map[string]interface{}{
152					"storage_path":            cfg.StoragePath,
153					"auto_save_interval_secs": interval.Seconds(),
154				})
155			}
156		}
157	
158		return selector
159	}
160	
161	// SetStorage sets a custom storage backend (useful for testing)
162	func (e *EloSelector) SetStorage(storage EloStorage) {
163		e.storage = storage
164	}
165	
166	// loadFromStorage loads ratings from the storage backend
167	func (e *EloSelector) loadFromStorage() error {
168		if e.storage == nil {
169			return nil
170		}
171	
172		allRatings, err := e.storage.LoadAllRatings()
173		if err != nil {
174			return err
175		}
176	
177		e.globalMu.Lock()
178		e.categoryMu.Lock()
179		defer e.globalMu.Unlock()
180		defer e.categoryMu.Unlock()
181	
182		for category, ratings := range allRatings {
183			if category == "_global" {
184				for model, rating := range ratings {
185					e.globalRatings[model] = rating
186				}
187			} else {
188				if e.categoryRatings[category] == nil {
189					e.categoryRatings[category] = make(map[string]*ModelRating)
190				}
191				for model, rating := range ratings {
192					e.categoryRatings[category][model] = rating
193				}
194			}
195		}
196	
197		logging.ComponentEvent("selection", "elo_ratings_loaded", map[string]interface{}{
198			"categories_loaded": len(allRatings),
199		})
200		return nil
201	}
202	
203	// getAllRatingsForStorage returns all ratings in a format suitable for storage
204	func (e *EloSelector) getAllRatingsForStorage() map[string]map[string]*ModelRating {
205		e.globalMu.RLock()
206		e.categoryMu.RLock()
207		defer e.globalMu.RUnlock()
208		defer e.categoryMu.RUnlock()
209	
210		result := make(map[string]map[string]*ModelRating)
211	
212		// Add global ratings (deep copy to avoid data races with concurrent updates)
213		if len(e.globalRatings) > 0 {
214			result["_global"] = make(map[string]*ModelRating, len(e.globalRatings))
215			for k, v := range e.globalRatings {
216				copied := *v
217				result["_global"][k] = &copied
218			}
219		}
220	
221		// Add category ratings (deep copy)
222		for cat, ratings := range e.categoryRatings {
223			result[cat] = make(map[string]*ModelRating, len(ratings))
224			for k, v := range ratings {
225				copied := *v
226				result[cat][k] = &copied
227			}
228		}
229	
230		return result
231	}
232	
233	// Close stops storage operations and persists final state
234	func (e *EloSelector) Close() error {
235		if e.storage != nil {
236			return e.storage.Close()
237		}
238		return nil
239	}
240	
241	// Method returns the selection method type
242	func (e *EloSelector) Method() SelectionMethod {
243		return MethodElo
244	}
245	
246	// SetModelCost sets the cost per 1M tokens for a model
247	func (e *EloSelector) SetModelCost(model string, costPer1M float64) {
248		e.costMu.Lock()
249		defer e.costMu.Unlock()
250		e.modelCosts[model] = costPer1M
251	}
252	
253	// InitializeFromConfig sets up initial ratings from model configuration
254	func (e *EloSelector) InitializeFromConfig(modelConfig map[string]config.ModelParams, categories []config.Category) {
255		e.globalMu.Lock()
256		defer e.globalMu.Unlock()
257	
258		// Initialize global ratings for all models
259		for model := range modelConfig {
260			if _, exists := e.globalRatings[model]; !exists {
261				e.globalRatings[model] = &ModelRating{
262					Model:  model,
263					Rating: e.config.InitialRating,
264				}
265			}
266		}
267	
268		// Set costs from config
269		e.costMu.Lock()
270		for model, params := range modelConfig {
271			if params.Pricing.PromptPer1M > 0 {
272				e.modelCosts[model] = params.Pricing.PromptPer1M
273			}
274		}
275		e.costMu.Unlock()
276	
277		// Initialize category ratings from ModelScores if available
278		if e.config.CategoryWeighted {
279			e.categoryMu.Lock()
280			for _, category := range categories {
281				if e.categoryRatings[category.Name] == nil {
282					e.categoryRatings[category.Name] = make(map[string]*ModelRating)
283				}
284				for _, ms := range category.ModelScores {
285					// Convert static scores to Elo ratings (scale 0-1 -> 1000-2000)
286					rating := EloMinRatingFromScore + (ms.Score * EloRatingRange)
287					e.categoryRatings[category.Name][ms.Model] = &ModelRating{
288						Model:  ms.Model,
289						Rating: rating,
290					}
291				}
292			}
293			e.categoryMu.Unlock()
294		}
295	}
296	
297	// Select chooses the best model based on Elo ratings
298	func (e *EloSelector) Select(ctx context.Context, selCtx *SelectionContext) (*SelectionResult, error) {
299		if err := ValidateSelectionContext(selCtx); err != nil {
300			return nil, err
301		}
302	
303		allScores := make(map[string]float64)
304	
305		// Get ratings for all candidates
306		ratings := e.getRatingsForCandidates(selCtx.DecisionName, selCtx.CandidateModels)
307	
308		logging.Infof("[EloSelector] Evaluating %d candidates for category '%s':",
309			len(selCtx.CandidateModels), selCtx.DecisionName)
310		for _, r := range ratings {
311			logging.Infof("[EloSelector]   %s: rating=%.1f (W:%d L:%d T:%d)",
312				r.Model, r.Rating, r.Wins, r.Losses, r.Ties)
313		}
314	
315		// Calculate selection probability using Bradley-Terry model
316		// P(model_i wins) = rating_i / sum(all ratings)
317		totalRating := 0.0
318		for _, r := range ratings {
319			totalRating += math.Pow(10, r.Rating/400.0) // Standard Elo probability scale
320		}
321	
322		if totalRating == 0 {
323			// Fallback: uniform distribution
324			for _, r := range ratings {
325				allScores[r.Model] = 1.0 / float64(len(ratings))
326			}
327		} else {
328			for _, r := range ratings {
329				prob := math.Pow(10, r.Rating/400.0) / totalRating
330				allScores[r.Model] = prob
331			}
332		}
333	
334		// Apply cost adjustment if enabled
335		if e.config.CostScalingFactor > 0 && selCtx.CostWeight > 0 {
336			e.applyCostAdjustment(allScores, selCtx.CostWeight)
337		}
338	
339		// Find best model by combined score
340		var bestModel *config.ModelRef
341		var bestScore float64
342		var bestRating *ModelRating
343	
344		for i := range selCtx.CandidateModels {
345			model := &selCtx.CandidateModels[i]
346			score := allScores[model.Model]
347	
348			if score > bestScore || bestModel == nil {
349				bestScore = score
350				bestModel = model
351				for _, r := range ratings {
352					if r.Model == model.Model {
353						bestRating = r
354						break
355					}
356				}
357			}
358		}
359	
360		if bestModel == nil {
361			return nil, fmt.Errorf("could not select a model")
362		}
363	
364		// Calculate confidence based on rating stability
365		confidence := e.calculateConfidence(bestRating)
366	
367		reasoning := fmt.Sprintf("Selected based on Elo rating %.1f (win rate: %d/%d)",
368			bestRating.Rating,
369			bestRating.Wins,
370			bestRating.Wins+bestRating.Losses+bestRating.Ties)
371	
372		if e.config.CategoryWeighted && selCtx.DecisionName != "" {
373			reasoning = fmt.Sprintf("Category '%s': %s", selCtx.DecisionName, reasoning)
374		}
375	
376		logging.Infof("[EloSelector] Selected model %s (rating=%.1f, score=%.4f, confidence=%.2f)",
377			bestModel.Model, bestRating.Rating, bestScore, confidence)
378	
379		// Record metrics for all candidate models' current Elo ratings
380		for _, r := range ratings {
381			category := selCtx.DecisionName
382			if category == "" {
383				category = "_global"
384			}
385			RecordEloRating(r.Model, category, r.Rating)
386		}
387	
388		return &SelectionResult{
389			SelectedModel: bestModel.Model,
390			LoRAName:      bestModel.LoRAName,
391			Score:         bestScore,
392			Confidence:    confidence,
393			Method:        MethodElo,
394			Reasoning:     reasoning,
395			AllScores:     allScores,
396		}, nil
397	}
398	
399	// UpdateFeedback updates Elo ratings based on user preference feedback.
400	// Supports three modes:
401	// 1. Comparison: Both WinnerModel and LoserModel set - standard Elo update
402	// 2. Positive self-feedback: Only WinnerModel set - small rating boost
403	// 3. Negative self-feedback: Only LoserModel set - small rating penalty
404	func (e *EloSelector) UpdateFeedback(ctx context.Context, feedback *Feedback) error {
405		if err := NormalizeFeedback(feedback); err != nil {
406			return err
407		}
408	
409		e.updateGlobalRatings(feedback)
410	
411		if e.config.CategoryWeighted && feedback.DecisionName != "" {
412			e.updateCategoryRatings(feedback)
413		}
414	
415		logging.Infof("[EloSelector] Updated ratings: winner=%s, loser=%s, tie=%v",
416			feedback.WinnerModel, feedback.LoserModel, feedback.Tie)
417	
418		e.persistRatings()
419	
420		return nil
421	}
422	
423	// updateGlobalRatings updates global Elo ratings and records metrics.
424	func (e *EloSelector) updateGlobalRatings(feedback *Feedback) {
425		var winnerOldElo, loserOldElo float64
426		var globalWinnerStats, globalLoserStats ModelRating
427		var hasGlobalWinner bool
428		e.globalMu.Lock()
429		if r := e.globalRatings[feedback.WinnerModel]; r != nil {
430			winnerOldElo = r.Rating
431		} else {
432			winnerOldElo = e.config.InitialRating
433		}
434		if r := e.globalRatings[feedback.LoserModel]; r != nil {
435			loserOldElo = r.Rating
436		} else {
437			loserOldElo = e.config.InitialRating
438		}
439		e.updateRatingLocked(feedback, e.globalRatings)
440		if r := e.globalRatings[feedback.WinnerModel]; r != nil {
441			hasGlobalWinner = true
442			globalWinnerStats = *r
443		}
444		if r := e.globalRatings[feedback.LoserModel]; r != nil {
445			globalLoserStats = *r
446		}
447		e.globalMu.Unlock()
448	
449		if hasGlobalWinner {
450			RecordFeedbackMetrics(&FeedbackMetrics{
451				Winner:       feedback.WinnerModel,
452				Loser:        feedback.LoserModel,
453				Category:     "_global",
454				IsTie:        feedback.Tie,
455				WinnerOldElo: winnerOldElo,
456				WinnerNewElo: globalWinnerStats.Rating,
457				LoserOldElo:  loserOldElo,
458				LoserNewElo:  globalLoserStats.Rating,
459				WinnerStats:  globalWinnerStats,
460				LoserStats:   globalLoserStats,
461			})
462		}
463	}
464	
465	// updateCategoryRatings updates category-specific Elo ratings and records metrics.
466	func (e *EloSelector) updateCategoryRatings(feedback *Feedback) {
467		var catWinnerOldElo, catLoserOldElo float64
468		var catWinnerStats, catLoserStats ModelRating
469		var hasCatWinner bool
470	
471		e.categoryMu.Lock()
472		catRatings := e.categoryRatings[feedback.DecisionName]
473		if catRatings == nil {
474			catRatings = make(map[string]*ModelRating)
475			e.categoryRatings[feedback.DecisionName] = catRatings
476		}
477		if r := catRatings[feedback.WinnerModel]; r != nil {
478			catWinnerOldElo = r.Rating
479		} else {
480			catWinnerOldElo = e.config.InitialRating
481		}
482		if r := catRatings[feedback.LoserModel]; r != nil {
483			catLoserOldElo = r.Rating
484		} else {
485			catLoserOldElo = e.config.InitialRating
486		}
487		e.updateRatingLocked(feedback, catRatings)
488		if r := catRatings[feedback.WinnerModel]; r != nil {
489			hasCatWinner = true
490			catWinnerStats = *r
491		}
492		if r := catRatings[feedback.LoserModel]; r != nil {
493			catLoserStats = *r
494		}
495		e.categoryMu.Unlock()
496	
497		if hasCatWinner {
498			RecordFeedbackMetrics(&FeedbackMetrics{
499				Winner:       feedback.WinnerModel,
500				Loser:        feedback.LoserModel,
501				Category:     feedback.DecisionName,
502				IsTie:        feedback.Tie,
503				WinnerOldElo: catWinnerOldElo,
504				WinnerNewElo: catWinnerStats.Rating,
505				LoserOldElo:  catLoserOldElo,
506				LoserNewElo:  catLoserStats.Rating,
507				WinnerStats:  catWinnerStats,
508				LoserStats:   catLoserStats,
509			})
510		}
511	}
512	
513	// persistRatings marks storage as dirty for auto-save, or saves immediately for single updates.
514	func (e *EloSelector) persistRatings() {
515		if e.storage == nil {
516			return
517		}
518		if fileStorage, ok := e.storage.(*FileEloStorage); ok {
519			fileStorage.MarkDirty()
520		} else {
521			if err := e.storage.SaveAllRatings(e.getAllRatingsForStorage()); err != nil {
522				logging.Warnf("[EloSelector] Failed to save ratings to storage: %v", err)
523			}
524		}
525	}
526	
527	// updateRatingLocked performs the actual Elo rating update directly on the given ratings map.
528	// The caller must hold the appropriate write lock for the duration of this call.
529	func (e *EloSelector) updateRatingLocked(feedback *Feedback, ratings map[string]*ModelRating) {
530		// Handle self-feedback (single model, no comparison)
531		// This is used for automatic signal-based feedback where we only know
532		// if one model did well or poorly, not compared to another
533		if feedback.LoserModel == "" && feedback.WinnerModel != "" {
534			e.applyWinnerOnlyFeedbackLocked(feedback.WinnerModel, ratings)
535			return
536		}
537	
538		if feedback.WinnerModel == "" && feedback.LoserModel != "" {
539			e.applyLoserOnlyFeedbackLocked(feedback.LoserModel, ratings)
540			return
541		}
542	
543		// Standard two-model comparison
544		if feedback.WinnerModel == "" {
545			return // No valid feedback
546		}
547	
548		e.applyPairwiseFeedbackLocked(feedback, ratings)
549	}
550	
551	func (e *EloSelector) applyWinnerOnlyFeedbackLocked(model string, ratings map[string]*ModelRating) {
552		// Positive self-feedback: model did well
553		rating := ratings[model]
554		if rating == nil {
555			rating = &ModelRating{Model: model, Rating: e.config.InitialRating}
556		}
557		// Apply small positive adjustment (reward)
558		rating.Rating += e.config.KFactor * 0.1 // 10% of K-factor for self-feedback
559		rating.Comparisons++
560		rating.Wins++
561		ratings[model] = rating
562	}
563	
564	func (e *EloSelector) applyLoserOnlyFeedbackLocked(model string, ratings map[string]*ModelRating) {
565		// Negative self-feedback: model did poorly
566		rating := ratings[model]
567		if rating == nil {
568			rating = &ModelRating{Model: model, Rating: e.config.InitialRating}
569		}
570		// Apply small negative adjustment (penalty)
571		rating.Rating -= e.config.KFactor * 0.1 // 10% of K-factor for self-feedback
572		rating.Comparisons++
573		rating.Losses++
574		ratings[model] = rating
575	}
576	
577	func (e *EloSelector) applyPairwiseFeedbackLocked(feedback *Feedback, ratings map[string]*ModelRating) {
578		winnerRating := ratings[feedback.WinnerModel]
579		if winnerRating == nil {
580			winnerRating = &ModelRating{Model: feedback.WinnerModel, Rating: e.config.InitialRating}
581		}
582	
583		loserRating := ratings[feedback.LoserModel]
584		if loserRating == nil {
585			loserRating = &ModelRating{Model: feedback.LoserModel, Rating: e.config.InitialRating}
586		}
587	
588		// Calculate expected scores using Bradley-Terry model
589		// E_a = 1 / (1 + 10^((R_b - R_a) / 400))
590		expectedWinner := 1.0 / (1.0 + math.Pow(10, (loserRating.Rating-winnerRating.Rating)/400.0))
591		expectedLoser := 1.0 - expectedWinner
592	
593		// Determine actual scores
594		actualWinner, actualLoser := 1.0, 0.0
595		if feedback.Tie {
596			actualWinner = 0.5
597			actualLoser = 0.5
598		}
599	
600		// Update ratings: R' = R + K * (actual - expected)
601		winnerRating.Rating += e.config.KFactor * (actualWinner - expectedWinner)
602		loserRating.Rating += e.config.KFactor * (actualLoser - expectedLoser)
603	
604		// Update statistics
605		winnerRating.Comparisons++
606		loserRating.Comparisons++
607		if feedback.Tie {
608			winnerRating.Ties++
609			loserRating.Ties++
610		} else {
611			winnerRating.Wins++
612			loserRating.Losses++
613		}
614	
615		ratings[feedback.WinnerModel] = winnerRating
616		ratings[feedback.LoserModel] = loserRating
617	}
618	
619	// getRatingsForCandidates retrieves ratings for all candidate models
620	func (e *EloSelector) getRatingsForCandidates(decisionName string, candidates []config.ModelRef) []*ModelRating {
621		ratings := make([]*ModelRating, 0, len(candidates))
622	
623		for _, c := range candidates {
624			var rating *ModelRating
625	
626			// Try category-specific rating first
627			if e.config.CategoryWeighted && decisionName != "" {
628				rating = e.getCategoryRating(decisionName, c.Model)
629			}
630	
631			// Fall back to global rating
632			if rating == nil {
633				rating = e.getGlobalRating(c.Model)
634			}
635	
636			// Create default rating if not found
637			if rating == nil {
638				rating = &ModelRating{
639					Model:  c.Model,
640					Rating: e.config.InitialRating,
641				}
642			}
643	
644			ratings = append(ratings, rating)
645		}
646	
647		return ratings
648	}
649	
650	// getGlobalRating retrieves the global rating for a model
651	func (e *EloSelector) getGlobalRating(model string) *ModelRating {
652		e.globalMu.RLock()
653		defer e.globalMu.RUnlock()
654		return e.globalRatings[model]
655	}
656	
657	// setGlobalRating sets the global rating for a model
658	func (e *EloSelector) setGlobalRating(model string, rating *ModelRating) {
659		e.globalMu.Lock()
660		defer e.globalMu.Unlock()
661		e.globalRatings[model] = rating
662	}
663	
664	// getCategoryRating retrieves the category-specific rating for a model
665	func (e *EloSelector) getCategoryRating(category, model string) *ModelRating {
666		e.categoryMu.RLock()
667		defer e.categoryMu.RUnlock()
668		if catRatings, ok := e.categoryRatings[category]; ok {
669			return catRatings[model]
670		}
671		return nil
672	}
673	
674	// setCategoryRating sets the category-specific rating for a model
675	func (e *EloSelector) setCategoryRating(category, model string, rating *ModelRating) {
676		e.categoryMu.Lock()
677		defer e.categoryMu.Unlock()
678		if e.categoryRatings[category] == nil {
679			e.categoryRatings[category] = make(map[string]*ModelRating)
680		}
681		e.categoryRatings[category][model] = rating
682	}
683	
684	// applyCostAdjustment adjusts scores based on model costs
685	func (e *EloSelector) applyCostAdjustment(scores map[string]float64, costWeight float64) {
686		e.costMu.RLock()
687		defer e.costMu.RUnlock()
688	
689		if len(e.modelCosts) == 0 {
690			return
691		}
692	
693		// Find min and max costs for normalization
694		minCost, maxCost := math.MaxFloat64, 0.0
695		for model := range scores {
696			if cost, ok := e.modelCosts[model]; ok {
697				if cost < minCost {
698					minCost = cost
699				}
700				if cost > maxCost {
701					maxCost = cost
702				}
703			}
704		}
705	
706		if maxCost == minCost {
707			return // All same cost, no adjustment needed
708		}
709	
710		// Adjust scores: cheaper models get bonus
711		for model := range scores {
712			if cost, ok := e.modelCosts[model]; ok {
713				// Normalize cost to 0-1 (0 = cheapest, 1 = most expensive)
714				normalizedCost := (cost - minCost) / (maxCost - minCost)
715				// Cost penalty: cheaper models get higher bonus
716				costBonus := (1.0 - normalizedCost) * costWeight * e.config.CostScalingFactor
717				scores[model] *= (1.0 + costBonus)
718			}
719		}
720	}
721	
722	// calculateConfidence returns confidence based on rating stability
723	func (e *EloSelector) calculateConfidence(rating *ModelRating) float64 {
724		if rating == nil {
725			return 0.5
726		}
727	
728		// Confidence increases with more comparisons
729		// Sigmoid function: 1 / (1 + e^(-k*(x-threshold)))
730		k := 0.2 // Steepness
731		threshold := float64(e.config.MinComparisons)
732		confidence := 1.0 / (1.0 + math.Exp(-k*(float64(rating.Comparisons)-threshold)))
733	
734		return confidence
735	}
736	
737	// GetLeaderboard returns models sorted by rating (for debugging/monitoring)
738	func (e *EloSelector) GetLeaderboard(category string) []*ModelRating {
739		var ratings []*ModelRating
740	
741		if category != "" && e.config.CategoryWeighted {
742			e.categoryMu.RLock()
743			if catRatings, ok := e.categoryRatings[category]; ok {
744				for _, r := range catRatings {
745					ratings = append(ratings, r)
746				}
747			}
748			e.categoryMu.RUnlock()
749		} else {
750			e.globalMu.RLock()
751			for _, r := range e.globalRatings {
752				ratings = append(ratings, r)
753			}
754			e.globalMu.RUnlock()
755		}
756	
757		// Sort by rating descending
758		sort.Slice(ratings, func(i, j int) bool {
759			return ratings[i].Rating > ratings[j].Rating
760		})
761	
762		return ratings
763	}
