64	// DefaultModelSelectionConfig returns the default configuration
65	func DefaultModelSelectionConfig() *ModelSelectionConfig {
66		return &ModelSelectionConfig{
67			Method: string(MethodStatic),
68		}
69	}
70	
71	// Factory creates and initializes selectors based on configuration
72	type Factory struct {
73		cfg           *ModelSelectionConfig
74		modelConfig   map[string]config.ModelParams
75		categories    []config.Category
76		embeddingFunc func(string) ([]float32, error)
77		lookupTable   lookuptable.LookupTable
78	}
79	
80	// NewFactory creates a new selector factory
81	func NewFactory(cfg *ModelSelectionConfig) *Factory {
82		if cfg == nil {
83			cfg = DefaultModelSelectionConfig()
84		}
85		return &Factory{
86			cfg: cfg,
87		}
88	}
89	
90	// WithModelConfig sets the model configuration
91	func (f *Factory) WithModelConfig(modelConfig map[string]config.ModelParams) *Factory {
92		f.modelConfig = modelConfig
93		return f
94	}
95	
96	// WithCategories sets the category configuration
97	func (f *Factory) WithCategories(categories []config.Category) *Factory {
98		f.categories = categories
99		return f
100	}
101	
102	// WithEmbeddingFunc sets the embedding function for RouterDC
103	func (f *Factory) WithEmbeddingFunc(fn func(string) ([]float32, error)) *Factory {
104		f.embeddingFunc = fn
105		return f
106	}
107	
108	// WithLookupTable sets the lookup table used by selectors that support data-driven
109	// constant resolution (e.g. HybridSelector's quality-gap threshold).
110	func (f *Factory) WithLookupTable(lt lookuptable.LookupTable) *Factory {
111		f.lookupTable = lt
112		return f
113	}
114	
115	// Create creates and initializes a selector based on the configured method
116	func (f *Factory) Create() Selector {
117		method := SelectionMethod(f.cfg.Method)
118	
119		var selector Selector
120	
121		switch method {
122		case MethodElo:
123			eloSelector := NewEloSelector(f.cfg.Elo)
124			if f.modelConfig != nil {
125				eloSelector.InitializeFromConfig(f.modelConfig, f.categories)
126			}
127			selector = eloSelector
128	
129		case MethodRouterDC:
130			routerDCSelector := NewRouterDCSelector(f.cfg.RouterDC)
131			if f.embeddingFunc != nil {
132				routerDCSelector.SetEmbeddingFunc(f.embeddingFunc)
133			}
134			// Initialize model embeddings from descriptions in model config
135			if f.modelConfig != nil {
136				if err := routerDCSelector.InitializeFromConfig(f.modelConfig); err != nil {
137					logging.Errorf("[SelectionFactory] RouterDC initialization failed: %v", err)
138				}
139			}
140			selector = routerDCSelector
141	
142		case MethodAutoMix:
143			autoMixSelector := NewAutoMixSelector(f.cfg.AutoMix)
144			if f.modelConfig != nil {
145				autoMixSelector.InitializeFromConfig(f.modelConfig)
146			}
147			selector = autoMixSelector
148	
149		case MethodHybrid:
150			hybridSelector := NewHybridSelector(f.cfg.Hybrid)
151			if f.modelConfig != nil {
152				hybridSelector.InitializeFromConfig(f.modelConfig, f.categories)
153			}
154			if f.embeddingFunc != nil && hybridSelector.routerDCSelector != nil {
155				hybridSelector.routerDCSelector.SetEmbeddingFunc(f.embeddingFunc)
156			}
157			if f.lookupTable != nil {
158				hybridSelector.SetLookupTable(f.lookupTable)
159			}
160			selector = hybridSelector
161	
162		case MethodGMTRouter:
163			gmtRouterSelector := NewGMTRouterSelector(f.cfg.GMTRouter)
164			if f.modelConfig != nil {
165				gmtRouterSelector.InitializeFromConfig(f.modelConfig)
166			}
167			if f.embeddingFunc != nil {
168				gmtRouterSelector.SetEmbeddingFunc(f.embeddingFunc)
169			}
170			selector = gmtRouterSelector
171	
172		case MethodRLDriven:
173			rlDrivenSelector := NewRLDrivenSelector(f.cfg.RLDriven)
174			if f.modelConfig != nil {
175				rlDrivenSelector.InitializeFromConfig(f.modelConfig, f.categories)
176			}
177			selector = rlDrivenSelector
178	
179		case MethodLatencyAware:
180			selector = NewLatencyAwareSelector(nil)
181	
182		case MethodMultiFactor:
183			multiFactorSelector := NewMultiFactorSelector(f.cfg.MultiFactor)
184			if f.modelConfig != nil {
185				multiFactorSelector.InitializeFromConfig(f.modelConfig)
186			}
187			selector = multiFactorSelector
188	
189		default:
190			// Default to static selector
191			staticSelector := NewStaticSelector(DefaultStaticConfig())
192			if f.categories != nil {
193				staticSelector.InitializeFromConfig(f.categories)
194			}
195			selector = staticSelector
196		}
197	
198		logging.Infof("[SelectionFactory] Created selector: method=%s", method)
199		return selector
200	}
201	
202	// CreateAll creates all available selectors and registers them
203	func (f *Factory) CreateAll() *Registry {
204		// Initialize metrics for model selection tracking
205		InitializeMetrics()
206	
207		registry := NewRegistry()
208	
209		// Always create static selector
210		staticSelector := NewStaticSelector(DefaultStaticConfig())
211		if f.categories != nil {
212			staticSelector.InitializeFromConfig(f.categories)
213		}
214		registry.Register(MethodStatic, staticSelector)
215	
216		// Create Elo selector
217		eloCfg := f.cfg.Elo
218		if eloCfg == nil {
219			eloCfg = DefaultEloConfig()
220		}
221		eloSelector := NewEloSelector(eloCfg)
222		if f.modelConfig != nil {
223			eloSelector.InitializeFromConfig(f.modelConfig, f.categories)
224		}
225		registry.Register(MethodElo, eloSelector)
226	
227		// Create RouterDC selector
228		routerDCCfg := f.cfg.RouterDC
229		if routerDCCfg == nil {
230			routerDCCfg = DefaultRouterDCConfig()
231		}
232		routerDCSelector := NewRouterDCSelector(routerDCCfg)
233		if f.embeddingFunc != nil {
234			routerDCSelector.SetEmbeddingFunc(f.embeddingFunc)
235		}
236		// Initialize model embeddings from descriptions in model config
237		if f.modelConfig != nil {
238			if err := routerDCSelector.InitializeFromConfig(f.modelConfig); err != nil {
239				logging.Errorf("[SelectionFactory] RouterDC initialization failed: %v", err)
240			}
241		}
242		registry.Register(MethodRouterDC, routerDCSelector)
243	
244		// Create AutoMix selector
245		autoMixCfg := f.cfg.AutoMix
246		if autoMixCfg == nil {
247			autoMixCfg = DefaultAutoMixConfig()
248		}
249		autoMixSelector := NewAutoMixSelector(autoMixCfg)
250		if f.modelConfig != nil {
251			autoMixSelector.InitializeFromConfig(f.modelConfig)
252		}
253		registry.Register(MethodAutoMix, autoMixSelector)
254	
255		// Create Hybrid selector with component references
256		hybridCfg := f.cfg.Hybrid
257		if hybridCfg == nil {
258			hybridCfg = DefaultHybridConfig()
259		}
260		hybridSelector := NewHybridSelectorWithComponents(hybridCfg, eloSelector, routerDCSelector, autoMixSelector)
261		if f.modelConfig != nil {
262			hybridSelector.InitializeFromConfig(f.modelConfig, f.categories)
263		}
264		if f.lookupTable != nil {
265			hybridSelector.SetLookupTable(f.lookupTable)
266		}
267		registry.Register(MethodHybrid, hybridSelector)
268	
269		// Create ML-based selectors (KNN, KMeans, SVM)
270		mlCfg := f.cfg.ML
271		if mlCfg == nil {
272			mlCfg = DefaultMLSelectorConfig()
273		}
274	
275		// Create KNN selector
276		knnAdapter, err := CreateKNNSelector(mlCfg, f.embeddingFunc)
277		if err != nil {
278			logging.Warnf("[SelectionFactory] Failed to create KNN selector: %v", err)
279		} else {
280			registry.Register(MethodKNN, knnAdapter)
281		}
282	
283		// Create KMeans selector
284		kmeansAdapter, err := CreateKMeansSelector(mlCfg, f.embeddingFunc)
285		if err != nil {
286			logging.Warnf("[SelectionFactory] Failed to create KMeans selector: %v", err)
287		} else {
288			registry.Register(MethodKMeans, kmeansAdapter)
289		}
290	
291		// Create SVM selector
292		svmAdapter, err := CreateSVMSelector(mlCfg, f.embeddingFunc)
293		if err != nil {
294			logging.Warnf("[SelectionFactory] Failed to create SVM selector: %v", err)
295		} else {
296			registry.Register(MethodSVM, svmAdapter)
297		}
298	
299		// Create MLP selector (GPU-accelerated via Candle)
300		mlpAdapter, err := CreateMLPSelector(mlCfg, f.embeddingFunc)
301		if err != nil {
302			logging.Warnf("[SelectionFactory] Failed to create MLP selector: %v", err)
303		} else {
304			registry.Register(MethodMLP, mlpAdapter)
305		}
306	
307		// Create RL-Driven selector
308		rlDrivenCfg := f.cfg.RLDriven
309		if rlDrivenCfg == nil {
310			rlDrivenCfg = DefaultRLDrivenConfig()
311		}
312		rlDrivenSelector := NewRLDrivenSelector(rlDrivenCfg)
313		if f.modelConfig != nil {
314			rlDrivenSelector.InitializeFromConfig(f.modelConfig, f.categories)
315		}
316		registry.Register(MethodRLDriven, rlDrivenSelector)
317	
318		// Create GMTRouter selector
319		gmtRouterCfg := f.cfg.GMTRouter
320		if gmtRouterCfg == nil {
321			gmtRouterCfg = DefaultGMTRouterConfig()
322		}
323		gmtRouterSelector := NewGMTRouterSelector(gmtRouterCfg)
324		if f.modelConfig != nil {
325			gmtRouterSelector.InitializeFromConfig(f.modelConfig)
326		}
327		if f.embeddingFunc != nil {
328			gmtRouterSelector.SetEmbeddingFunc(f.embeddingFunc)
329		}
330		registry.Register(MethodGMTRouter, gmtRouterSelector)
331	
332		// Create LatencyAware selector
333		latencyAwareSelector := NewLatencyAwareSelector(nil)
334		registry.Register(MethodLatencyAware, latencyAwareSelector)
335	
336		// Create MultiFactor selector
337		multiFactorSelector := NewMultiFactorSelector(f.cfg.MultiFactor)
338		if f.modelConfig != nil {
339			multiFactorSelector.InitializeFromConfig(f.modelConfig)
340		}
341		registry.Register(MethodMultiFactor, multiFactorSelector)
342	
343		LogRegisteredAlgorithms(registry)
344		logging.ComponentEvent("selection", "selection_factory_initialized", map[string]interface{}{
345			"selector_count": len(registry.selectors),
346		})
347		return registry
348	}
349	
350	// LogRegisteredAlgorithms logs the tier and dependencies of each registered algorithm
351	func LogRegisteredAlgorithms(registry *Registry) {
352		registry.mu.RLock()
353		defer registry.mu.RUnlock()
354	
355		for method, selector := range registry.selectors {
356			deps := selector.ExternalDependencies()
357			if len(deps) == 0 {
358				logging.Infof("[Selection] Registered algorithm: %s (tier=%s, dependencies=none)", method, selector.Tier())
359			} else {
360				depNames := make([]string, len(deps))
361				for i, dep := range deps {
362					depNames[i] = fmt.Sprintf("%s (%s)", dep.Name, dep.Type)
363				}
364				logging.Infof("[Selection] Registered algorithm: %s (tier=%s, dependencies=[%s])",
365					method, selector.Tier(), strings.Join(depNames, ", "))
366			}
367		}
368	}
369	
370	// WarnExperimentalAlgorithms logs prominent warnings for experimental algorithms
371	// that are actually configured in operator decisions
372	func WarnExperimentalAlgorithms(registry *Registry, configuredMethods []SelectionMethod) {
373		for _, method := range configuredMethods {
374			selector, ok := registry.Get(method)
375			if !ok {
376				continue
377			}
378			if selector.Tier() != TierExperimental {
379				continue
380			}
381	
382			deps := selector.ExternalDependencies()
383			logging.Warnf("[Selection] WARNING: Algorithm %q is EXPERIMENTAL and not recommended for production use", method)
384			for _, dep := range deps {
385				if dep.HealthURL != "" {
386					logging.Warnf("[Selection]   External dependency: %s (%s)", dep.Name, dep.HealthURL)
387				} else {
388					logging.Warnf("[Selection]   Dependency: %s — %s", dep.Name, dep.Description)
389				}
390			}
391		}
392	}
393	
394	// CheckDependencyHealth checks reachability of external service dependencies
395	// for the given algorithms. Logs results but never fails.
396	func CheckDependencyHealth(registry *Registry, configuredMethods []SelectionMethod) {
397		for _, method := range configuredMethods {
398			selector, ok := registry.Get(method)
399			if !ok {
400				continue
401			}
402	
403			for _, dep := range selector.ExternalDependencies() {
404				if dep.Type != DependencyExternalService || dep.HealthURL == "" {
405					continue
406				}
407	
408				ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
409				client := &http.Client{Timeout: 5 * time.Second}
410				req, err := http.NewRequestWithContext(ctx, "GET", dep.HealthURL, nil)
411				if err != nil {
412					logging.Warnf("[Selection] Dependency check: %s — UNREACHABLE (bad URL: %v)", dep.Name, err)
413					cancel()
414					continue
415				}
416	
417				resp, err := client.Do(req)
418				cancel()
419				if err != nil {
420					logging.Warnf("[Selection] Dependency check: %s at %s — UNREACHABLE (will degrade at runtime)", dep.Name, dep.HealthURL)
421				} else {
422					_ = resp.Body.Close()
423					if resp.StatusCode == http.StatusOK {
424						logging.Infof("[Selection] Dependency check: %s at %s — OK", dep.Name, dep.HealthURL)
425					} else {
426						logging.Warnf("[Selection] Dependency check: %s at %s — unhealthy (status %d)", dep.Name, dep.HealthURL, resp.StatusCode)
427					}
428				}
429			}
430		}
431	}
432	
433	// Initialize sets up the global registry with all selectors
434	func Initialize(cfg *ModelSelectionConfig, modelConfig map[string]config.ModelParams, categories []config.Category, embeddingFunc func(string) ([]float32, error)) {
435		factory := NewFactory(cfg).
436			WithModelConfig(modelConfig).
437			WithCategories(categories).
438			WithEmbeddingFunc(embeddingFunc)
439	
440		// Create all selectors and register globally
441		GlobalRegistry = factory.CreateAll()
442	
443		logging.ComponentEvent("selection", "selection_registry_initialized", map[string]interface{}{
444			"selector_count": len(GlobalRegistry.selectors),
445		})
446	}
447	
448	// GetSelector returns a selector for the specified method from global registry
449	func GetSelector(method SelectionMethod) Selector {
450		selector, ok := GlobalRegistry.Get(method)
451		if !ok {
452			// Fallback to static
453			selector, _ = GlobalRegistry.Get(MethodStatic)
454		}
455		return selector
456	}
