package selection

import (
	"errors"
	"fmt"
	"strings"
)

var (
	ErrSelectionContextRequired  = errors.New("selection context is required")
	ErrCandidateModelsRequired   = errors.New("no candidate models provided")
	ErrCandidateModelNameMissing = errors.New("candidate model name is required")
)

// ValidateSelectionContext checks the common public selector input contract.
func ValidateSelectionContext(selCtx *SelectionContext) error {
	if selCtx == nil {
		return ErrSelectionContextRequired
	}
	if len(selCtx.CandidateModels) == 0 {
		return ErrCandidateModelsRequired
	}
	for i, modelRef := range selCtx.CandidateModels {
		if strings.TrimSpace(modelRef.Model) == "" {
			return fmt.Errorf("%w: candidate_models[%d]", ErrCandidateModelNameMissing, i)
		}
	}
	return nil
}

