28	// StaticConfig configures the static selector
29	type StaticConfig struct {
30		// UseFirstCandidate always selects the first candidate (default behavior)
31		UseFirstCandidate bool `yaml:"use_first_candidate"`
32	
33		// CategoryScores maps category -> model -> score (from config)
34		CategoryScores map[string]map[string]float64 `yaml:"-"`
35	}
36	
37	// DefaultStaticConfig returns the default Static configuration
38	func DefaultStaticConfig() *StaticConfig {
39		return &StaticConfig{
40			UseFirstCandidate: true,
41			CategoryScores:    make(map[string]map[string]float64),
42		}
43	}
44	
45	// StaticSelector implements static model selection based on configuration scores
46	// This is the baseline selector that uses pre-configured scores without learning.
47	type StaticSelector struct {
48		config *StaticConfig
49	
50		// Category-specific scores from configuration
51		categoryScores map[string]map[string]float64
52		scoresMu       sync.RWMutex
53	}
54	
55	// NewStaticSelector creates a new Static selector
56	func NewStaticSelector(cfg *StaticConfig) *StaticSelector {
57		if cfg == nil {
58			cfg = DefaultStaticConfig()
59		}
60		return &StaticSelector{
61			config:         cfg,
62			categoryScores: make(map[string]map[string]float64),
63		}
64	}
65	
66	// Method returns the selection method type
67	func (s *StaticSelector) Method() SelectionMethod {
68		return MethodStatic
69	}
70	
71	// InitializeFromConfig sets up static scores from model configuration
72	func (s *StaticSelector) InitializeFromConfig(categories []config.Category) {
73		s.scoresMu.Lock()
74		defer s.scoresMu.Unlock()
75	
76		for _, category := range categories {
77			if s.categoryScores[category.Name] == nil {
78				s.categoryScores[category.Name] = make(map[string]float64)
79			}
80			for _, ms := range category.ModelScores {
81				s.categoryScores[category.Name][ms.Model] = ms.Score
82			}
